self.FRX=self.FRX||{};(FRX.gx=FRX.gx||{})["ru"]={"etre-present":["Être: быть","\"être\" значит «быть»: \"je suis\", \"tu es\", \"il est\", \"nous sommes\", \"vous êtes\", \"ils sont\". Глагол нужен для личности, происхождения, профессии и описания. Выучите наизусть: это самый частый глагол французского. Примеры: \"je suis\", \"nous sommes\", \"ils sont\"."],"avoir-present":["Avoir: иметь","\"avoir\" значит «иметь»: \"j'ai\", \"tu as\", \"il a\", \"nous avons\", \"vous avez\", \"ils ont\". Он же образует passé composé (о нём позже). Обратите внимание на элизию \"j'ai\" перед гласным звуком. Примеры: \"j'ai\", \"elle a\", \"nous avons\"."],"il-y-a":["Il y a: есть, имеется","\"il y a\" вводит то, что существует, в единственном и во множественном числе, и не меняется: \"il y a un livre\", \"il y a des livres\". Отрицание: \"il n'y a pas de livre\". Вопрос: \"y a-t-il\" или \"est-ce qu'il y a\". Примеры: \"il y a un café\", \"il n'y a pas de lait\"."],"art-defini":["Определённые артикли","\"le\" (муж. р.), \"la\" (жен. р.), \"l'\" (перед гласным) и \"les\" (мн. ч.) передают определённость, как «тот самый»; по-русски артикля нет. Во французском их ставят и для общих понятий: \"j'aime la musique\" значит «я люблю музыку». Примеры: \"le café\", \"la pomme\", \"les enfants\"."],"art-indefini":["Неопределённые артикли","\"un\" (муж. р.), \"une\" (жен. р.) и \"des\" (мн. ч.) значат «какой-то, некий, несколько». Они вводят нечто новое: \"j'ai un frère et des cousins\". \"des\" по-русски часто не переводится. Примеры: \"un frère\", \"une sœur\", \"des amis\"."],"gender-nouns":["Мужской или женский род?","У каждого существительного есть род. Подсказывают окончания: \"-tion\", \"-té\", \"-ette\" чаще женские, \"-ment\", \"-age\", \"-eau\" чаще мужские. Всегда учите слово с артиклем: \"la ville\", \"le village\". Примеры: \"le village\", \"la ville\", \"la question\"."],"plural-regular":["Множественное число: добавляем -s","Обычно во мн. ч. добавляется \"-s\", но оно не произносится: \"un ami\", \"des amis\". Слова на \"-s\", \"-x\", \"-z\" не меняются: \"un pays\", \"des pays\". Множественное число выдают только артикль и liaison. Примеры: \"deux sœurs\", \"trois amis\"."],"plural-irregular":["Особые формы множественного числа","Слова на \"-al\" меняются на \"-aux\": \"un journal\", \"des journaux\". Слова на \"-eau\" и \"-eu\" получают \"-x\": \"un bateau\", \"des bateaux\", \"un jeu\", \"des jeux\". Исключения (например \"un festival, des festivals\") просто запомните. Примеры: \"des journaux\", \"des bateaux\", \"des cheveux\"."],"elision-basic":["Элизия перед гласным","Короткие слова \"le\", \"la\", \"je\", \"ne\", \"de\", \"que\", \"se\" теряют гласную перед гласным или немым h и получают апостроф: \"l'école\", \"j'aime\", \"n'aime pas\", \"qu'elle\". \"les\" и \"un\" никогда не элидируются. Примеры: \"l'école\", \"j'aime\", \"qu'elle\"."],"contractions-au-du":["Слитные формы au, aux, du, des","\"à + le\" превращается в \"au\", \"à + les\" в \"aux\", \"de + le\" в \"du\", \"de + les\" в \"des\". С \"la\" и \"l'\" ничего не меняется: \"à la gare\", \"de la gare\". Никогда не пишите \"à le\" или \"de le\". Примеры: \"au marché\", \"aux voisins\", \"du professeur\"."],"partitif":["Партитивный артикль: «некоторое количество»","Когда речь о неисчисляемом количестве, используйте \"du\" (муж.), \"de la\" (жен.), \"de l'\" (перед гласным) или \"des\" (мн.): \"je prends du café\". По-русски слова тут обычно нет, а во французском оно обязательно. Примеры: \"du pain\", \"de la salade\", \"des légumes\"."],"de-negation":["Отрицание + de","После \"ne… pas\", \"jamais\", \"plus\" неопределённый и партитивный артикли превращаются в \"de\": \"j'ai un chat\" → \"je n'ai pas de chat\". Исключение: после \"être\" артикль сохраняется: \"ce n'est pas un chat\". Примеры: \"pas de voiture\", \"jamais de viande\"."],"adj-agreement":["Согласование прилагательных","Прилагательные согласуются с существительным: для женского рода добавляем \"-e\", для мн. числа \"-s\": \"grand\", \"grande\", \"grands\", \"grandes\". Прилагательные на -e в женском роде не меняются: \"un garçon sympa\", \"une fille sympa\". Примеры: \"elle est grande\", \"ils sont petits\"."],"adj-position":["Где стоит прилагательное?","Большинство прилагательных стоят после существительного: \"une robe bleue\". Несколько коротких частых ставятся перед ним: красота, возраст, качество, размер (\"beau, jeune, bon, grand, petit\"): \"un petit chien\". У \"beau\" есть формы \"bel\" и \"belle\". Примеры: \"une belle maison\", \"une maison blanche\"."],"possessifs":["Притяжательные: mon, ma, mes","Притяжательное согласуется с предметом, а не с владельцем: \"mon père\", \"ma mère\", \"mes parents\". Перед гласным женские слова берут \"mon\": \"mon amie\". Другие: \"notre/nos\", \"votre/vos\", \"leur/leurs\". Примеры: \"mon père\", \"ma mère\", \"leurs chats\"."],"demonstratifs":["Указательные: ce, cette, ces","\"ce\" (муж.), \"cet\" (муж. перед гласным), \"cette\" (жен.) и \"ces\" (мн.) значат «этот» или «тот». Для противопоставления добавьте \"-ci\" или \"-là\": \"ce livre-ci\", \"ce livre-là\". Примеры: \"ce livre\", \"cette veste\", \"ces enfants\"."],"pres-er":["Présent: глаголы на -er","Отбросьте \"-er\" и добавьте \"-e, -es, -e, -ons, -ez, -ent\": \"parler\" даёт \"je parle\", \"tu parles\", \"il parle\", \"nous parlons\", \"vous parlez\", \"ils parlent\". По этому образцу спрягается около 90 процентов французских глаголов. Примеры: \"je parle\", \"nous parlons\", \"ils parlent\"."],"pres-ir-re":["Présent: глаголы на -ir и -re","Правильные глаголы на \"-ir\" получают \"-is, -is, -it, -issons, -issez, -issent\": \"finir\", \"je finis\", \"nous finissons\". Глаголы на \"-re\" получают \"-s, -s, -, -ons, -ez, -ent\": \"vendre\", \"je vends\", \"il vend\". Примеры: \"je finis\", \"nous finissons\", \"je vends\"."],"pres-irreguliers":["Частые неправильные глаголы","Выучите \"aller\" (\"je vais, nous allons\"), \"faire\" (\"je fais, vous faites\"), \"prendre\" (\"je prends, ils prennent\") и \"venir\" (\"je viens, ils viennent\"). Осторожно: \"vous faites\" и \"ils font\" выбиваются из правила. Примеры: \"je vais\", \"nous faisons\", \"ils prennent\", \"vous venez\"."],"tu-vous":["Tu или vous?","\"tu\" говорите друзьям, родным, детям и ровесникам. \"vous\" говорите незнакомым, старшим, в магазине и на работе, а также всегда, когда обращаетесь к нескольким людям. Сомневаетесь, начинайте с \"vous\". Примеры: \"tu viens\", \"vous venez\"."],"on-nous":["On = мы","В повседневной речи \"on\" заменяет \"nous\", но глагол остаётся в 3-м лице ед. числа: \"on va au cinéma\". \"On\" также значит «люди вообще»: \"en France, on mange du pain\". Примеры: \"on va\", \"on mange\"."],"neg-ne-pas":["Отрицание: ne … pas","Ставьте \"ne\" перед глаголом, а \"pas\" после него: \"je ne parle pas\". Перед гласным \"ne\" превращается в \"n'\": \"il n'aime pas\". В разговорной речи \"ne\" часто опускают, но в письме он нужен. Примеры: \"je ne parle pas\", \"il n'aime pas\"."],"q-est-ce-que":["Вопросы «да/нет»","Проще всего оставить порядок слов и повысить голос или поставить вопросительный знак: \"tu viens ?\". Формальнее: добавить \"est-ce que\" в начало: \"est-ce que tu viens ?\". Перед гласным получается \"est-ce qu'\": \"est-ce qu'elle vient ?\". Примеры: \"tu aimes le thé ?\", \"est-ce que vous avez\"."],"q-mots-interrogatifs":["Вопросительные слова","\"où\" (где), \"quand\" (когда), \"comment\" (как), \"combien\" (сколько), \"pourquoi\" (почему), \"qui\" (кто). Они стоят в начале: \"où est la gare ?\". На \"pourquoi\" отвечают с помощью \"parce que\". Примеры: \"où\", \"quand\", \"combien\", \"pourquoi\"."],"q-quel":["Quel: какой","\"quel\" согласуется с существительным: \"quel\" (м. ед.), \"quelle\" (ж. ед.), \"quels\" (м. мн.), \"quelles\" (ж. мн.). Может стоять и после существительного, с глаголом «быть»: \"être\", \"quel est ton nom ?\". Примеры: \"quelle heure\", \"quels films\"."],"futur-proche":["Ближайшее будущее: aller + инфинитив","Спрягайте \"aller\" в настоящем времени и добавьте инфинитив: \"je vais travailler\", \"nous allons manger\". Отрицание: \"je ne vais pas partir\". Это обычный способ говорить о планах в речи. Примеры: \"je vais manger\", \"elle va partir\"."],"pres-pronominaux":["Возвратные глаголы","У этих глаголов есть местоимение, согласованное с подлежащим: \"je me\", \"tu te\", \"il se\", \"nous nous\", \"vous vous\", \"ils se\". Примеры: \"se lever\", \"se coucher\", \"s'habiller\". Отрицание: \"je ne me lève pas\". Примеры: \"je me lève\", \"elle se couche\"."],"imperatif-present":["Повелительное наклонение","Берите формы настоящего времени для \"tu\", \"nous\", \"vous\" без местоимения: \"tu parles\" даёт \"parle !\", \"nous parlons\" даёт \"parlons !\", \"vous parlez\" даёт \"parlez !\". У глаголов на \"-er\" в форме \"tu\" пропадает конечное -s. Неправильные: \"sois, soyons, soyez\", \"aie, ayons, ayez\". Примеры: \"parle !\", \"parlons !\", \"parlez !\"."],"modaux-pouvoir-vouloir":["vouloir, pouvoir, devoir","После этих трёх глаголов идёт инфинитив: \"je veux manger\", \"tu peux venir\", \"nous devons partir\". Они неправильные: \"je veux, nous voulons\", \"je peux, nous pouvons\", \"je dois, nous devons\". Примеры: \"je veux partir\", \"tu peux\", \"nous devons\"."],"prep-lieu":["Где находится?","Частые слова места: \"dans\" (в), \"sur\" (на), \"sous\" (под), \"devant\" (перед), \"derrière\" (за), \"entre\" (между), \"à côté de\" (рядом с), \"près de\" (около). После \"de\" помните о слитных формах: \"à côté du parc\". Примеры: \"sur la table\", \"sous la table\", \"entre la poste et la banque\"."],"prep-a-chez-de":["à, chez, de","\"à\" употребляется с городами и местами: \"je vais à Lyon\". \"chez\" с людьми, их магазином или домом: \"chez le dentiste\", \"chez moi\". \"de\" показывает, откуда вы: \"je viens de Lyon\". Примеры: \"chez Marie\", \"à Lyon\", \"de la gare\"."],"nombres":["Числительные","Особые формы: \"soixante-dix\" (70), \"quatre-vingts\" (80, с -s), \"quatre-vingt-dix\" (90). \"et\" появляется в 21, 31, 41, 51, 61 и 71, но не в 81 и 91. Дефисы соединяют десятки и единицы. Примеры: \"vingt et un\", \"soixante-dix\", \"quatre-vingts\"."],"heure-date":["Время и даты","Говорите \"il est\" + час: \"il est trois heures et quart\". \"midi\" и \"minuit\" берут \"et demi\", остальные часы \"et demie\". Даты: \"le 5 mai\", только первое число порядковое: \"le premier mai\". Для времени нужен \"à\": \"à neuf heures\". Примеры: \"huit heures et demie\", \"le cinq mai\"."],"c-est-ce-sont":["C'est, ce sont","\"c'est\" + существительное в ед. числе и \"ce sont\" + существительное во мн. числе: так представляют и определяют предмет: \"c'est un livre\", \"ce sont des livres\". В речи \"c'est\" часто употребляют и с множественным числом. Вопрос: \"qu'est-ce que c'est ?\". Примеры: \"c'est mon frère\", \"ce sont mes amis\"."],"gouts-aimer":["Что нравится, что нет","После \"aimer\", \"adorer\", \"détester\" и \"préférer\" ставится определённый артикль, а не партитивный: \"j'aime le café\", \"elle adore les chats\". Добавьте \"beaucoup\": \"j'aime beaucoup la musique\". Примеры: \"j'aime le chocolat\", \"je déteste les épinards\"."],"adv-intensite":["Насколько?","\"très\" стоит перед прилагательными и наречиями: \"très bien\". \"beaucoup\" стоит после глаголов: \"il travaille beaucoup\". Перед существительным нужно \"beaucoup de\": \"beaucoup de fruits\". \"un peu\" и \"trop\" ведут себя как \"beaucoup\". Примеры: \"très grand\", \"il mange beaucoup\", \"un peu\"."],"avoir-expressions":["Выражения с avoir","Для возраста и многих ощущений французы используют \"avoir\", а не \"être\": \"j'ai vingt ans\", \"j'ai faim\", \"j'ai soif\", \"j'ai chaud\", \"j'ai froid\", \"j'ai peur\", \"j'ai sommeil\". Добавьте \"très\": \"j'ai très faim\". Примеры: \"j'ai faim\", \"elle a vingt ans\", \"il a froid\"."],"clause-et-mais-parce-que":["Соединительные слова","\"et\" добавляет, \"ou\" даёт выбор, \"mais\" противопоставляет, \"parce que\" объясняет причину. Перед гласным \"parce que\" превращается в \"parce qu'\": \"parce qu'il pleut\". \"donc\" даёт следствие. Примеры: \"et\", \"mais\", \"parce que\"."],"pc-avoir":["Passé composé с avoir","Большинство глаголов образуют прошедшее время с \"avoir\" в настоящем + причастие: \"j'ai mangé\", \"tu as fini\", \"il a vendu\". Причастия: \"-er\" даёт \"-é\", \"-ir\" даёт \"-i\", \"-re\" даёт \"-u\". Примеры: \"j'ai mangé\", \"nous avons fini\"."],"pc-etre":["Passé composé с être","Около пятнадцати глаголов берут \"être\": \"aller, venir, arriver, partir, entrer, sortir, monter, descendre, rester, tomber, naître, mourir, retourner, passer\" и все возвратные глаголы. Запомнить помогает список \"DR MRS VANDERTRAMP\". Примеры: \"je suis allé\", \"elle est partie\"."],"pc-accord-etre":["Согласование причастия с être","С \"être\" причастие согласуется с подлежащим: для жен. рода добавьте \"-e\", для мн. числа \"-s\": \"il est parti\", \"elle est partie\", \"ils sont partis\", \"elles sont parties\". Примеры: \"elle est partie\", \"ils sont venus\", \"elles sont allées\"."],"pc-pronominaux":["Возвратные глаголы в прошедшем","Возвратные глаголы берут \"être\", а местоимение стоит перед ним: \"je me suis levé\", \"elle s'est couchée\", \"ils se sont promenés\". Причастие обычно согласуется с подлежащим. Примеры: \"je me suis levé\", \"elle s'est couchée\"."],"pc-negation":["Отрицание в прошедшем","\"ne … pas\" ставится вокруг вспомогательного глагола, а не причастия: \"je n'ai pas mangé\", \"elle n'est pas venue\". То же с \"jamais\", \"plus\", \"rien\": \"il n'a rien dit\". Примеры: \"je n'ai pas mangé\", \"il n'est jamais venu\"."],"pc-participes-irreguliers":["Неправильные причастия","Обязательные формы: \"avoir\" даёт \"eu\", \"être\" даёт \"été\", \"faire\" даёт \"fait\", \"prendre\" даёт \"pris\", \"voir\" даёт \"vu\", \"dire\" даёт \"dit\", \"écrire\" даёт \"écrit\", \"mettre\" даёт \"mis\", \"pouvoir\" даёт \"pu\", \"vouloir\" даёт \"voulu\". Примеры: \"j'ai eu\", \"j'ai été\", \"il a fait\", \"elle a pris\"."],"imparfait-formation":["Imparfait: образование","Возьмите форму \"nous\" настоящего времени, отбросьте \"-ons\", добавьте \"-ais, -ais, -ait, -ions, -iez, -aient\": \"nous parlons\" даёт \"je parlais\". Неправилен только \"être\": \"j'étais, nous étions\". Примеры: \"je jouais\", \"nous allions\", \"il était\"."],"imparfait-usage":["Imparfait: когда использовать","\"imparfait\" нужен для фона рассказа: погода, чувства, описания и повторяющиеся привычки. \"Il faisait beau\", \"j'étais fatigué\", \"chaque été, nous allions à la mer\". Примеры: \"il faisait beau\", \"je jouais\", \"nous habitions\"."],"impf-vs-pc":["Imparfait или passé composé?","\"Imparfait\": что происходило, обстановка. \"Passé composé\": что случилось, одно событие, двигающее рассказ. \"Je lisais quand le téléphone a sonné\": чтение шло, звонок его прервал. Примеры: \"je dormais\", \"le téléphone a sonné\"."],"futur-simple":["Futur simple","Возьмите инфинитив (у глаголов на \"-re\" отбросьте конечное -e) и добавьте \"-ai, -as, -a, -ons, -ez, -ont\": \"parler\" даёт \"je parlerai\", \"prendre\" даёт \"je prendrai\". Примеры: \"je parlerai\", \"nous prendrons\", \"ils finiront\"."],"futur-irreguliers":["Неправильные основы будущего","Окончания те же, но основа меняется: \"aller\" даёт \"ir-\", \"être\" даёт \"ser-\", \"avoir\" даёт \"aur-\", \"faire\" даёт \"fer-\", \"venir\" даёт \"viendr-\", \"pouvoir\" даёт \"pourr-\", \"voir\" даёт \"verr-\", \"vouloir\" даёт \"voudr-\". Примеры: \"j'irai\", \"il fera\", \"ils viendront\"."],"conditionnel-politesse":["Вежливое условное наклонение","\"conditionnel\" смягчает просьбы: \"je voudrais\" (я бы хотел), \"pourriez-vous\" (не могли бы вы), \"j'aimerais\" (мне бы очень хотелось). Образование: основа futur + окончания imparfait \"-ais, -ais, -ait, -ions, -iez, -aient\". Примеры: \"je voudrais\", \"pourriez-vous\", \"nous aimerions\"."],"cod-pronoms":["Прямое дополнение: местоимения","\"le\", \"la\", \"l'\" и \"les\" заменяют существительное без предлога и стоят перед глаголом: \"je vois Paul\" → \"je le vois\". Отрицание: \"je ne le vois pas\". Примеры: \"je le vois\", \"elle la prend\", \"tu les aimes\"."],"coi-pronoms":["Косвенное дополнение: местоимения","Для людей после \"à\" используйте \"lui\" (ему или ей) и \"leur\" (им): \"je parle à Marie\" → \"je lui parle\", \"je téléphone à mes parents\" → \"je leur téléphone\". \"leur\" здесь никогда не берёт -s. Примеры: \"je lui parle\", \"elle leur écrit\"."],"pronoms-me-te-nous-vous":["me, te, nous, vous","Эти четыре местоимения подходят и для прямого, и для косвенного дополнения: \"il me voit\", \"il me parle\". Перед гласным \"me\" и \"te\" превращаются в \"m'\" и \"t'\": \"je t'aime\", \"il m'écoute\". Примеры: \"il me voit\", \"elle nous parle\"."],"y-pronom":["Местоимение y","\"y\" заменяет \"à\" + предмет или место: \"je vais à Rome\" → \"j'y vais\". Оно стоит перед глаголом: \"nous y allons\", \"je n'y vais pas\". Также \"j'y pense\". Примеры: \"j'y vais\", \"nous y allons\"."],"en-pronom":["Местоимение en","\"en\" заменяет \"du, de la, des\" + существительное или \"de\" + существительное. Количество сохраняется: \"j'ai deux frères\" → \"j'en ai deux\". Отрицание: \"je n'en veux pas\". Примеры: \"j'en veux\", \"nous en avons deux\"."],"pronoms-toniques":["Ударные местоимения","Используйте \"moi, toi, lui, elle, nous, vous, eux, elles\" после предлогов (\"avec moi\", \"chez eux\"), для выделения (\"moi, je\") и отдельно (\"Qui est là ? Moi !\"). Также после \"c'est\": \"c'est lui\". Примеры: \"avec moi\", \"chez lui\", \"eux\"."],"comparatifs":["Сравнение: plus … que","Используйте \"plus … que\" (больше), \"moins … que\" (меньше) и \"aussi … que\" (так же … как) вокруг прилагательного или наречия: \"elle est plus rapide que lui\". Для существительных: \"plus de … que\". Примеры: \"plus grand que\", \"moins cher que\", \"aussi rapide que\"."],"superlatifs":["Превосходная степень","Поставьте определённый артикль перед \"plus\" или \"moins\": \"le plus grand\", \"la plus belle\", \"les moins chers\". «Из» передаётся через \"de\": \"le plus grand de la classe\". Примеры: \"le plus grand\", \"la plus belle\", \"les moins chers\"."],"meilleur-mieux":["meilleur или mieux?","\"bon\" становится \"meilleur\" (прилагательное, согласуется): \"une meilleure idée\". \"bien\" становится \"mieux\" (наречие, не меняется): \"elle chante mieux\". Никогда не говорите \"plus bon\" или \"plus bien\". Примеры: \"meilleur\", \"mieux\", \"la meilleure idée\"."],"adverbes-ment":["Наречия на -ment","Добавьте \"-ment\" к женской форме прилагательного: \"lent\" даёт \"lentement\", \"heureux\" даёт \"heureusement\". После гласной добавляйте к мужской: \"vrai\" даёт \"vraiment\". \"-ent\" превращается в \"-emment\": \"prudent\" даёт \"prudemment\". Примеры: \"lentement\", \"vraiment\", \"prudemment\"."],"prep-pays-villes":["Страны и города","Города: \"à Paris\", \"de Paris\". Страны женского рода: \"en France\", \"de France\". Страны мужского рода: \"au Japon\", \"du Japon\". Страны во мн. числе: \"aux États-Unis\", \"des États-Unis\". Примеры: \"en France\", \"au Japon\", \"aux États-Unis\", \"à Paris\"."],"depuis-pendant-il-y-a":["depuis, pendant, il y a","\"depuis\" + настоящее время: то, что ещё продолжается (\"j'habite ici depuis deux ans\"). \"pendant\" + срок: как долго это длилось (\"j'ai dormi pendant huit heures\"). \"il y a\" + срок: как давно это было (\"il est parti il y a une heure\"). Примеры: \"depuis deux ans\", \"pendant trois heures\", \"il y a une heure\"."],"passe-recent":["Недавнее прошлое: venir de","Спрягайте \"venir\" в настоящем и добавьте \"de\" + инфинитив: \"je viens de finir\", \"nous venons de partir\". Перед гласным \"de\" превращается в \"d'\": \"il vient d'arriver\". Примеры: \"je viens de manger\", \"ils viennent de partir\"."],"imperatif-negatif":["Отрицательное повелительное","Поставьте \"ne … pas\" вокруг глагола в повелительном наклонении: \"ne pars pas !\", \"ne partons pas !\", \"ne partez pas !\". Местоимения остаются перед глаголом: \"ne le fais pas !\". Примеры: \"ne parle pas\", \"ne partez pas\"."],"imperatif-pronoms":["Повелительное с местоимениями","В утвердительном повелительном местоимение стоит после глагола через дефис: \"regarde-moi\", \"parlez-nous\", \"dis-lui\". \"me\" превращается в \"moi\". В отрицании порядок обычный: \"ne me regarde pas\". Примеры: \"regarde-moi\", \"dis-lui\", \"donne-le-moi\"."],"rel-qui-que":["qui и que","\"qui\" заменяет подлежащее: \"la femme qui habite ici\". \"que\" заменяет прямое дополнение: \"le film que nous regardons\". Перед гласным \"que\" превращается в \"qu'\": \"le livre qu'il lit\". Примеры: \"l'homme qui parle\", \"le livre que je lis\"."],"rel-ou":["où: где, когда","\"où\" связывает место или время с придаточной частью: \"la maison où elle habite\", \"le jour où nous sommes partis\". Работает и для места, и для времени. Примеры: \"la ville où j'habite\", \"le jour où\"."],"il-faut":["il faut","\"il faut\" + инфинитив значит «нужно»: \"il faut partir\". \"il faut\" + существительное значит «требуется»: \"il faut du temps\". Отрицание \"il ne faut pas\" значит «нельзя». Это безличный глагол: только \"il\". Примеры: \"il faut travailler\", \"il faut du temps\"."],"neg-jamais-plus-rien":["jamais, plus, rien, personne","Они заменяют \"pas\": \"ne … jamais\" (никогда), \"ne … plus\" (больше не), \"ne … rien\" (ничего), \"ne … personne\" (никого). \"rien\" и \"personne\" могут быть и подлежащим: \"personne ne vient\". Примеры: \"je ne mange jamais\", \"il ne travaille plus\", \"nous ne voyons personne\"."],"quantite-de":["Количество + de","После слов количества ставьте \"de\" без артикля: \"beaucoup de travail\", \"un peu de sucre\", \"assez de temps\", \"trop de monde\", \"peu de gens\", \"une bouteille d'eau\". Примеры: \"beaucoup de travail\", \"un peu de sucre\", \"trop de monde\"."],"c-est-il-est":["c'est или il est?","Используйте \"il est\" / \"elle est\" только с прилагательным или профессией: \"il est médecin\", \"elle est gentille\". Используйте \"c'est\", когда есть артикль или притяжательное: \"c'est un médecin\", \"c'est mon frère\". Примеры: \"c'est un médecin\", \"il est médecin\", \"elle est gentille\"."],"q-inversion":["Инверсия","В аккуратной речи глагол ставится перед подлежащим-местоимением через дефис: \"parlez-vous ?\", \"où vas-tu ?\", \"que font-ils ?\". Если глагол оканчивается на гласную, добавьте \"-t-\": \"aime-t-il ?\". Примеры: \"parlez-vous\", \"où vas-tu\", \"que font-ils\"."],"q-qui-que-quoi":["Кто и что","\"qui\" спрашивает о людях, \"que\" и \"qu'est-ce que\" о вещах: \"qu'est-ce que tu fais ?\". После предлога используйте \"qui\" (люди) или \"quoi\" (вещи): \"avec qui ?\", \"de quoi parles-tu ?\". Примеры: \"qui est-ce ?\", \"qu'est-ce que tu fais ?\", \"de quoi parles-tu ?\"."],"adj-irreguliers":["beau, nouveau, vieux","У этих трёх есть особая форма перед гласным в мужском роде: \"beau\" даёт \"bel\", \"nouveau\" даёт \"nouvel\", \"vieux\" даёт \"vieil\". Женский род: \"belle\", \"nouvelle\", \"vieille\". Множественное число: \"beaux\", \"nouveaux\", \"vieux\". Примеры: \"un bel homme\", \"une nouvelle voiture\", \"un vieil ami\"."],"connecteurs-temps":["Сначала, потом, наконец","\"d'abord\" (сначала), \"ensuite\" или \"puis\" (потом), \"après\" (после), \"enfin\" (наконец) выстраивают действия по порядку: \"d'abord je mange, puis je pars, enfin j'arrive\". Примеры: \"d'abord\", \"ensuite\", \"puis\", \"enfin\"."],"si-present-futur":["si + présent, futur","Для реальной возможности: \"si\" + настоящее время в условии, будущее (или повелительное) в следствии. \"si tu viens, je serai content\", \"si vous avez le temps, appelez-moi\". Никогда не ставьте будущее после \"si\". Перед \"il\" получается \"s'il\". Примеры: \"si tu viens, nous mangerons\", \"s'il pleut, je resterai\"."],"savoir-connaitre":["savoir или connaître?","\"savoir\" для фактов и умений: \"je sais nager\", \"je sais où il habite\". \"connaître\" для знакомства с людьми, местами и вещами: \"je connais Marie\", \"je connais cette ville\". Примеры: \"je sais nager\", \"je connais Paris\"."],"pres-irreguliers-2":["Ещё неправильные глаголы","Учите их группами: \"lire\" (\"nous lisons\"), \"dire\" (\"vous dites\"), \"écrire\" (\"ils écrivent\"), \"voir\" (\"nous voyons\"), \"boire\" (\"ils boivent\"). Форма \"nous\" помогает образовать imparfait. Примеры: \"nous lisons\", \"vous dites\", \"ils écrivent\"."],"meteo-il":["Погода","Используйте \"il fait\" + прилагательное (\"il fait beau, froid, chaud\") и глагол для дождя и снега (\"il pleut\", \"il neige\"). Подлежащее \"il\" пустое и не меняется. Вопрос: \"quel temps fait-il ?\". Примеры: \"il fait beau\", \"il pleut\", \"il neige\"."],"profession-sans-article":["Профессия без артикля","После \"être\" профессия, национальность или религия идут без артикля: \"il est médecin\", \"elle est française\". С прилагательным нужен \"c'est un\": \"c'est un bon médecin\". Примеры: \"elle est infirmière\", \"il est professeur\"."],"subj-il-faut-que":["Subjonctif: il faut que","После \"il faut que\" ставится subjonctif. Правильные глаголы: возьмите основу \"ils\" настоящего времени и добавьте \"-e, -es, -e, -ions, -iez, -ent\": \"ils partent\" даёт \"que je parte\". Формы \"nous\" и \"vous\" похожи на imparfait. Примеры: \"il faut que tu viennes\", \"il faut que je parte\"."],"subj-vouloir-que":["vouloir que + subjonctif","Если подлежащее меняется, \"vouloir que\", \"préférer que\", \"aimer mieux que\" и \"demander que\" требуют subjonctif: \"je veux que tu viennes\". Если подлежащее то же, используйте инфинитив: \"je veux venir\". Примеры: \"je veux que tu viennes\", \"elle veut que nous partions\"."],"subj-irreguliers":["Неправильный subjonctif","Выучите наизусть: \"être\" (\"que je sois\"), \"avoir\" (\"que j'aie, qu'il ait\"), \"aller\" (\"que j'aille\"), \"faire\" (\"que je fasse\"), \"pouvoir\" (\"que je puisse\"), \"savoir\" (\"que je sache\"), \"vouloir\" (\"que je veuille\"). Примеры: \"que je sois\", \"qu'il ait\", \"que nous allions\", \"qu'ils fassent\"."],"subj-emotions":["Чувства + subjonctif","После выражений эмоций (\"être content que\", \"être triste que\", \"regretter que\", \"avoir peur que\", \"être surpris que\") ставится subjonctif, если подлежащее меняется. Примеры: \"je suis content que tu sois là\", \"elle regrette que nous partions\"."],"subj-vs-indic":["Indicatif или subjonctif?","Уверенность требует indicatif: \"je pense que\", \"je sais que\", \"il est sûr que\". Сомнение, отрицание и воля требуют subjonctif: \"je ne pense pas que\", \"je doute que\", \"il faut que\". \"Penser que\" в вопросе допускает оба варианта. Примеры: \"je pense qu'il a raison\", \"je ne pense pas qu'il ait raison\"."],"subj-conjonctions":["Союзы + subjonctif","Некоторые союзы всегда требуют subjonctif: \"pour que\" (чтобы), \"avant que\" (прежде чем), \"bien que\" (хотя), \"à condition que\" (при условии, что), \"jusqu'à ce que\" (пока не). \"après que\" требует indicatif. Примеры: \"pour que tu comprennes\", \"avant que tu partes\", \"bien qu'il soit fatigué\"."],"si-imparfait-cond":["si + imparfait, conditionnel","Для воображаемых или маловероятных ситуаций: \"si\" + imparfait, а в следствии условное наклонение. \"si j'étais riche, je voyagerais\". Никогда не ставьте условное после \"si\". Примеры: \"si j'avais de l'argent\", \"j'achèterais une maison\"."],"cond-usage":["Условное: советы и желания","\"conditionnel\" используют для советов (\"tu devrais\"), желаний (\"j'aimerais\") и вежливых предложений (\"on pourrait\"). С \"devoir\", \"pouvoir\" и \"vouloir\" оно очень частое. Примеры: \"tu devrais dormir\", \"nous aimerions voyager\"."],"cond-passe-regret":["Сожаления о прошлом","Для того, чего не случилось: \"si\" + plus-que-parfait, conditionnel passé. \"si tu avais étudié, tu aurais réussi\". Conditionnel passé: \"avoir\" или \"être\" в условном наклонении + причастие. Примеры: \"si j'avais su\", \"je serais venu\"."],"plus-que-parfait-forme":["Plus-que-parfait: образование","Вспомогательный глагол в \"imparfait\" + причастие: \"j'avais mangé\", \"elle était partie\", \"nous nous étions levés\". Выбор между \"avoir\" и \"être\" и согласование те же, что в passé composé. Примеры: \"j'avais fini\", \"nous étions partis\", \"elle avait mangé\"."],"plus-que-parfait-usage":["Plus-que-parfait: употребление","Используйте \"plus-que-parfait\" для действия, предшествовавшего другому действию в прошлом или моменту в прошлом: \"quand je suis arrivé, il était déjà parti\". Он часто объясняет причину: \"il était fatigué, il n'avait pas dormi\". Примеры: \"le film avait déjà commencé\", \"il n'avait pas dormi\"."],"di-present":["Косвенная речь (настоящее)","С \"dire que\", \"répondre que\", \"expliquer que\" в настоящем времени время придаточной не меняется, меняются только местоимения и слова вроде \"mon\": \"« j'ai faim »\" → \"il dit qu'il a faim\". Примеры: \"il dit qu'il est fatigué\", \"elle répond qu'elle ne sait pas\"."],"di-questions":["Косвенные вопросы","Вопросы «да/нет» вводятся через \"si\": \"il demande si tu viens\". Вопросительные слова остаются: \"où, quand, comment, pourquoi\". \"Qu'est-ce que\" превращается в \"ce que\", \"qu'est-ce qui\" в \"ce qui\". Порядок слов как в утверждении. Примеры: \"il demande si je viens\", \"elle demande où j'habite\"."],"di-passe":["Косвенная речь (прошедшее)","После \"a dit que\" времена сдвигаются назад: настоящее становится \"imparfait\", futur становится \"conditionnel\", passé composé становится \"plus-que-parfait\". Слова времени тоже меняются: \"demain\" становится \"le lendemain\". Примеры: \"il a dit qu'il était fatigué\", \"elle a répondu qu'elle viendrait\"."],"gerondif-formation":["Gérondif: образование","Возьмите форму \"nous\" настоящего времени, отбросьте \"-ons\", добавьте \"-ant\" и поставьте \"en\" перед ним: \"nous travaillons\" даёт \"en travaillant\". Исключения: \"être\" даёт \"en étant\", \"avoir\" даёт \"en ayant\", \"savoir\" даёт \"en sachant\". Примеры: \"en travaillant\", \"en lisant\", \"en finissant\"."],"gerondif-usage":["Gérondif: употребление","\"gérondif\" показывает, что два действия происходят одновременно (\"il chante en travaillant\"), способ действия (\"on apprend en lisant\") или условие (\"en tournant à gauche, vous verrez la poste\"). У обоих глаголов одно подлежащее. Примеры: \"on apprend en lisant\", \"il s'est blessé en jouant\"."],"rel-dont":["dont: о котором, чей","\"dont\" заменяет \"de\" + существительное: \"je parle de ce livre\" → \"le livre dont je parle\". Также значит «чей»: \"la fille dont le père est médecin\". И после \"avoir besoin de\": \"ce dont j'ai besoin\". Примеры: \"le livre dont je parle\", \"la fille dont le père est médecin\"."],"rel-ce-qui-ce-que":["ce qui, ce que, ce dont","Когда перед ним нет существительного, используйте \"ce qui\" (подлежащее), \"ce que\" (дополнение) и \"ce dont\" (с \"de\"): \"ce qui se passe\", \"ce que tu veux\", \"ce dont j'ai besoin\". Примеры: \"ce que tu veux\", \"ce qui se passe\", \"ce dont j'ai besoin\"."],"pronoms-ordre":["Два местоимения подряд","Порядок перед глаголом: \"me, te, nous, vous\" + \"le, la, les\" + \"lui, leur\" + \"y\" + \"en\". \"me le\", \"te la\", \"nous les\", но \"le lui\", \"les leur\": \"je le lui donne\". Примеры: \"je le lui donne\", \"elle me les envoie\"."],"y-en-ensemble":["il y en a","Когда есть и \"y\", и \"en\", \"y\" стоит первым: \"il y en a\", \"il n'y en a plus\". \"en\" сохраняет количество: \"il y en a trois\". Примеры: \"il y en a\", \"nous y en avons\"."],"imperatif-ordre-pronoms":["Повелительное: порядок местоимений","Утверждение: глагол + прямое дополнение (\"le, la, les\") + косвенное (\"moi, lui, nous, leur\") + \"y\" / \"en\": \"donne-le-moi\", \"dis-le-lui\". \"moi\" превращается в \"m'\" перед \"en\": \"donne-m'en\". Отрицание: обычный порядок, \"ne me le donne pas\". Примеры: \"donne-le-moi\", \"dis-le-lui\", \"donne-m'en\"."],"pronoms-possessifs":["Притяжательные местоимения","Они заменяют притяжательное + существительное и согласуются с ним: \"le mien, la mienne, les miens, les miennes\", \"le tien\", \"le sien\", \"le nôtre\", \"le vôtre\", \"le leur\". \"Où est ma clé ? — Voici la mienne.\" Примеры: \"le mien\", \"la tienne\", \"les nôtres\"."],"pronoms-demonstratifs":["celui, celle, ceux, celles","Они значат «тот, та, те» и за ними следуют \"de\", \"qui\", \"que\" или \"-ci / -là\": \"celui de gauche\", \"celle qui est ici\", \"ceux de Marc\", \"celles-là\". Примеры: \"celui de gauche\", \"celle qui est ici\", \"ceux de Marc\"."],"pronoms-indefinis":["Неопределённые местоимения","\"quelqu'un\" (кто-то), \"quelque chose\" (что-то), \"personne\" (никто), \"rien\" (ничего), \"chacun\" (каждый), \"plusieurs\" (несколько). Перед прилагательным нужен \"de\": \"quelque chose de bon\". Примеры: \"quelqu'un\", \"quelque chose de sucré\", \"chacun\"."],"adj-indefinis":["chaque, plusieurs, quelques","\"chaque\" + существительное в ед. числе (каждый), \"plusieurs\" и \"quelques\" + существительное во мн. числе (несколько). \"tout\" согласуется: \"tout le monde\", \"toute la journée\", \"tous les jours\", \"toutes les semaines\". Примеры: \"chaque élève\", \"plusieurs voitures\", \"toute la journée\"."],"pc-accord-cod":["Согласование причастия с avoir","С \"avoir\" причастие согласуется с прямым дополнением только если оно стоит перед глаголом: \"j'ai acheté des fleurs\", но \"les fleurs que j'ai achetées\", \"je les ai vues\". Примеры: \"les fleurs que j'ai achetées\", \"je les ai vues\"."],"passif-forme":["Страдательный залог","\"être\" (в нужном времени) + причастие, согласованное с подлежащим + \"par\": \"la lettre est écrite par Paul\", \"les maisons ont été détruites par le feu\". Дополнение действительного предложения становится подлежащим. Примеры: \"le roman est écrit par\", \"la porte est ouverte par\"."],"se-passif":["Страдательный залог с se","Глагол в 3-м лице с \"se\" получает пассивное значение без деятеля: \"le vin se vend ici\", \"ça ne se dit pas\", \"cela se voit\". Очень част в речи и в правилах. Примеры: \"ça se dit\", \"ce produit se vend partout\"."],"etre-en-train-de":["être en train de","\"être en train de\" + инфинитив подчёркивает, что действие идёт прямо сейчас: \"je suis en train de lire\". Это аналог английского -ing, когда нужно подчеркнуть: \"ne l'appelle pas, il est en train de dormir\". Примеры: \"je suis en train de manger\", \"ils sont en train de partir\"."],"pc-avoir-transitif":["Один глагол, два вспомогательных","Когда у \"sortir, monter, descendre, passer, rentrer, retourner\" есть прямое дополнение, вспомогательный глагол \"avoir\": \"j'ai sorti la voiture\", \"elle a monté les escaliers\". Без дополнения \"être\": \"elle est sortie\". Примеры: \"il a sorti la valise\", \"elle a monté les escaliers\"."],"futur-anterieur":["Futur antérieur","\"avoir\" или \"être\" в futur simple + причастие: \"j'aurai fini\", \"elle sera partie\". Описывает действие, завершённое до другого будущего действия: \"quand j'aurai fini, je t'appellerai\". Примеры: \"quand j'aurai fini\", \"dès qu'elle sera arrivée\"."],"quand-futur":["quand + будущее","В отличие от русского и английского, французский ставит будущее после \"quand\", \"dès que\", \"lorsque\" и \"aussitôt que\", если действие в будущем: \"dès qu'il arrivera, nous partirons\". \"Si\" исключение: после него будущего не бывает. Примеры: \"quand je serai grand\", \"dès qu'il arrivera\"."],"connecteurs-cause-consequence":["Причина и следствие","\"car\" и \"parce que\" дают причину, \"comme\" и \"puisque\" открывают предложение известной причиной: \"comme il pleut, je reste\". \"donc\" и \"alors\" дают следствие: \"il pleut, donc je reste\". Примеры: \"donc\", \"car\", \"comme\", \"puisque\"."],"connecteurs-opposition":["Противопоставление","\"mais\", \"pourtant\" и \"cependant\" противопоставляют две мысли. \"alors que\" сравнивает два факта: \"elle aime le thé, alors que son mari préfère le café\". \"malgré\" + существительное значит «несмотря на»: \"malgré la pluie\". Примеры: \"pourtant\", \"alors que\", \"malgré la pluie\"."],"but-pour-afin-de":["Цель","При одном подлежащем: \"pour\" или \"afin de\" + инфинитив: \"je travaille pour gagner de l'argent\". При разных подлежащих: \"pour que\" или \"afin que\" + subjonctif: \"il parle lentement pour que nous comprenions\". Примеры: \"pour gagner de l'argent\", \"afin de rentrer\", \"pour que nous comprenions\"."],"neg-ne-que-ni":["ne … que, ni … ni, aucun","\"ne … que\" значит «только»: \"je n'ai que dix euros\". \"ne … ni … ni\" значит «ни … ни»: \"elle ne mange ni viande ni poisson\". \"ne … aucun\" значит «ни один»: \"il n'a aucun ami\". Примеры: \"je n'ai que dix euros\", \"ni viande ni poisson\", \"aucun ami\"."],"neg-infinitif":["Отрицательный инфинитив","Обе части отрицания стоят вместе перед инфинитивом: \"ne pas partir\", \"ne plus fumer\", \"ne jamais mentir\". \"Il m'a demandé de ne pas fumer\". Примеры: \"ne pas fumer\", \"ne plus travailler\", \"ne jamais mentir\"."],"q-lequel":["Lequel: который из","\"lequel\" заменяет \"quel\" + существительное и согласуется: \"lequel\" (м. ед.), \"laquelle\" (ж. ед.), \"lesquels\" (м. мн.), \"lesquelles\" (ж. мн.). \"Quel sac ? Lequel ?\" После \"à\" и \"de\": \"auquel\", \"duquel\". Примеры: \"lequel\", \"laquelle\", \"lesquels\"."],"exclamations":["Восклицания","\"quel\" + существительное: \"quelle belle journée !\". \"comme\" или \"que\" + предложение: \"comme il fait chaud !\", \"que c'est joli !\". Обратите внимание на пробел перед \"!\" во французском. Примеры: \"quelle belle journée !\", \"comme il fait chaud !\", \"que c'est joli !\"."],"adv-place-pc":["Короткие наречия в passé composé","Короткие частые наречия (\"déjà, bien, mal, souvent, toujours, encore, trop, beaucoup\") стоят между вспомогательным глаголом и причастием: \"j'ai déjà mangé\", \"il a bien compris\". Наречия места и длинные наречия стоят после. Примеры: \"elle a déjà fini\", \"il a bien compris\"."],"comparatifs-avances":["Всё больше, чем … тем","\"de plus en plus\" (всё больше), \"de moins en moins\" (всё меньше), \"plus … plus\" (чем … тем), \"autant de … que\" (столько же … сколько): \"elle a autant de livres que moi\". Примеры: \"de plus en plus froid\", \"plus on travaille, plus on apprend\", \"autant de livres\"."],"prep-verbes":["Глаголы с предлогом","Многим глаголам нужен постоянный предлог: \"penser à\", \"s'intéresser à\", \"répondre à\", \"parler de\", \"avoir besoin de\", \"avoir envie de\", \"rêver de\". Учите их вместе с глаголом. Примеры: \"penser à\", \"parler de\", \"avoir besoin de\", \"s'intéresser à\"."],"prep-temps-en-dans":["en или dans?","\"dans\" + срок: когда что-то случится, считая от сейчас (\"le film commence dans une heure\"). \"en\" + срок: сколько что-то длится (\"il a lu ce livre en deux jours\"). \"en\" ещё употребляется с месяцами и годами: \"en mai\", \"en 1998\". Примеры: \"dans une heure\", \"en deux jours\"."],"inf-apres-prepositions":["Предлоги + инфинитив","\"avant de\" + инфинитив, \"après\" + прошедший инфинитив (\"avoir\" или \"être\" + причастие), \"sans\" + инфинитив: \"avant de partir\", \"après avoir mangé\", \"sans dire au revoir\". Подлежащее должно быть одно и то же. Примеры: \"avant de manger\", \"après avoir mangé\", \"sans dire\"."],"faire-causatif":["faire + инфинитив","\"faire\" + инфинитив значит «велеть сделать» (\"je fais réparer ma voiture\") или «заставить кого-то» (\"il fait rire les enfants\"). Инфинитив идёт сразу за \"faire\". Примеры: \"je fais réparer ma voiture\", \"il fait rire les enfants\"."],"verbes-perception":["Видеть и слышать + инфинитив","После \"voir\", \"entendre\", \"regarder\", \"écouter\", \"sentir\" ставится инфинитив: \"je les entends jouer\", \"nous voyons passer le train\". Местоимение является дополнением глагола восприятия. Примеры: \"je les entends chanter\", \"nous voyons passer le train\"."],"voyelle-liaison-ecrite":["Особые формы перед гласным","Перед гласным или немым h некоторые слова меняются для удобства произношения: \"ma\" превращается в \"mon\" (\"mon amie\"), \"ce\" в \"cet\" (\"cet homme\"), \"beau\" в \"bel\" (\"un bel arbre\"), \"nouveau\" в \"nouvel\", \"vieux\" в \"vieil\". Примеры: \"mon amie\", \"cet homme\", \"un bel arbre\"."],"tout-tous-toutes":["tout, tous, toute, toutes","Как прилагательное \"tout\" согласуется: \"tout le monde\", \"toute la journée\", \"tous les jours\", \"toutes les semaines\". Как местоимение оно значит «всё» (\"j'ai tout compris\") или «все» (\"ils sont tous là\", с произносимым -s). Примеры: \"tous les jours\", \"toute la journée\", \"ils sont tous là\"."],"subj-after-bien-que":["Bien que + сослагательное","\"bien que\", \"quoique\" и \"encore que\" выражают уступку и всегда требуют сослагательного наклонения (subjonctif), даже если факт несомненен. Говорят \"Bien que le projet soit coûteux, nous continuons\", а не \"bien que le projet est\". Примеры: \"Bien qu'il pleuve, nous sortons\", \"Quoiqu'elle soit jeune, elle dirige l'équipe\"."],"subj-after-pour-que":["Цель: pour que, afin que","\"pour que\" и \"afin que\" вводят цель, после них идёт сослагательное. Подлежащее придаточного обычно отличается от главного: \"Je répète pour que vous compreniez\". Если подлежащее одно, используют \"pour\" или \"afin de\" с инфинитивом. Примеры: \"Il parle lentement pour que nous comprenions\", \"Elle écrit afin que tout soit clair\"."],"subj-after-avant-que":["Срок: avant que","\"avant que\" и \"jusqu'à ce que\" требуют сослагательного, потому что действие ещё не совершено. После \"avant que\" часто добавляют \"ne\" без отрицательного смысла: \"avant qu'il ne parte\". При одном подлежащем используйте \"avant de\" с инфинитивом. Примеры: \"Attends jusqu'à ce que je revienne\", \"Appelle avant que nous ne partions\"."],"subj-a-moins-que-ne":["Исключение: à moins que","\"à moins que\" значит \"если только не\" и требует сослагательного. В формальной речи перед глаголом часто ставят пустое \"ne\" (\"à moins qu'il ne vienne\"), это не настоящее отрицание. После него нельзя использовать условное наклонение и будущее время. Примеры: \"Je sors, à moins qu'il ne pleuve\", \"à moins que vous ne soyez occupé\"."],"subj-a-condition-que":["Условие: à condition que","\"à condition que\" и \"pourvu que\" значат \"при условии, что\" и требуют сослагательного, но не будущего и не условного. \"Pourvu que\" может начинать фразу, выражая надежду: \"Pourvu qu'il vienne !\". Примеры: \"Je viendrai à condition que vous m'invitiez\", \"Pourvu que tout se passe bien\"."],"subj-vs-ind-opinion":["Глаголы мнения: выбор наклонения","После \"penser que\" и \"croire que\" в утверждении ставят изъявительное: \"Je pense qu'il a raison\". В отрицании или в вопросе с инверсией появляется сомнение, и нужно сослагательное: \"Je ne pense pas qu'il ait raison\". Наклонение зависит от уверенности говорящего. Примеры: \"Je crois qu'elle viendra\", \"Je ne crois pas qu'elle vienne\"."],"subj-emotion-doubt":["Чувство, сомнение, необходимость","После глаголов чувства (\"être content que\", \"regretter que\"), сомнения (\"douter que\") и необходимости (\"il faut que\", \"il est essentiel que\") ставится сослагательное, если подлежащие разные. Придаточное выражает реакцию или потребность, а не простой факт. Примеры: \"Je suis ravi que vous veniez\", \"Il faut que nous partions\"."],"subj-irregular-forms":["Неправильные основы сослагательного","У семи частых глаголов неправильные основы сослагательного: \"être\" (sois, soyons), \"avoir\" (aie, ayons), \"aller\" (aille, allions), \"faire\" (fasse), \"pouvoir\" (puisse), \"savoir\" (sache), \"vouloir\" (veuille). Учите их целыми формами; у форм nous и vous глаголов \"être\", \"avoir\", \"aller\" и \"vouloir\" тоже своя основа. Примеры: \"qu'elle aille\", \"que vous sachiez\", \"que tu aies\"."],"subj-passe":["Прошедшее сослагательное","Прошедшее сослагательное — это сослагательное \"avoir\" или \"être\" и причастие прошедшего времени. Оно показывает, что действие завершилось раньше действия главного глагола: \"Je suis content que tu sois venu\". Вспомогательный глагол выбирают как в passé composé и сохраняют согласование. Примеры: \"Il faut qu'ils aient fini\", \"Bien qu'elle soit partie\"."],"subj-vs-infinitive":["Сослагательное или инфинитив","Если подлежащее у обоих глаголов одно, французский предпочитает инфинитив: \"Je veux partir\". Если подлежащее меняется, нужно \"que\" и сослагательное: \"Je veux que tu partes\". То же верно для желаний, чувств и многих союзов (\"avant de\" или \"avant que\"). Примеры: \"Elle est contente d'être là\", \"Elle est contente que vous soyez là\"."],"subj-superlative-relative":["Сослагательное после превосходной степени","После превосходной степени (\"le plus\", \"le meilleur\") или \"seul\", \"premier\", \"dernier\", \"unique\" определительное придаточное ставится в сослагательном, потому что это личная оценка. С \"jamais\" часто употребляют прошедшее сослагательное: \"le plus beau film que j'aie vu\". Примеры: \"le seul homme qui sache\", \"la première fois que je le voie\"."],"subj-relative-search":["Сослагательное для искомого предмета","Когда определительное придаточное описывает то, что вы ищете, хотите или в существовании чего сомневаетесь, нужно сослагательное: \"Je cherche un livre qui soit simple\". Если вы знаете, что предмет существует, ставьте изъявительное: \"J'ai un livre qui est simple\". Типичные сигналы: \"chercher\", \"vouloir\", \"il n'y a personne qui\", вопросы о существовании. Пример: \"Y a-t-il quelqu'un qui puisse m'aider ?\"."],"cond-passe-news":["Условное для неподтверждённых новостей","Журналисты используют условное наклонение, часто прошедшее, чтобы передать неподтверждённые сведения: \"Le ministre aurait démissionné\". Оно означает \"якобы\" и снимает с автора ответственность за факт. Для текущего слуха — условное настоящее: \"Il serait malade\". Примеры: \"Deux personnes seraient blessées\", \"selon certaines sources, le vol aurait été annulé\"."],"si-plus-que-parfait":["Нереальное прошлое: si + plus-que-parfait","Для нереального условия в прошлом используют \"si\" и plus-que-parfait, а в следствии — прошедшее условное: \"Si j'avais su, je serais venu\". В таком значении после \"si\" никогда не ставят условное. Следствие показывает, что не произошло. Примеры: \"Si elle avait étudié, elle aurait réussi\", \"Si nous étions partis, nous aurions vu le concert\"."],"si-mixed-conditions":["Смешанные условные предложения","Смешанное условное предложение связывает условие в прошлом со следствием в настоящем: \"si\" и plus-que-parfait, затем условное настоящее. Слова времени вроде \"maintenant\" или \"aujourd'hui\" в следствии показывают, что результат верен и сейчас. Пример: \"Si tu avais écouté, tu comprendrais\". Сравните с полностью прошлой схемой: \"tu aurais compris\"."],"hypothese-au-cas-ou":["Предосторожность: au cas où","\"au cas où\" выражает предосторожность на случай возможного события, после него идёт условное наклонение, а не сослагательное и не будущее. Значит \"на случай, если\". Может стоять в начале или в конце фразы. Примеры: \"Prenez un parapluie au cas où il pleuvrait\", \"Au cas où tu serais en retard, appelle-moi\"."],"apres-que-indicatif":["après que + изъявительное","\"après que\" и \"dès que\" передают реально случившийся факт, поэтому после них ставится изъявительное, а не сослагательное (в отличие от \"avant que\"). Глагол после \"après que\" стоит в сложном времени, раньше главного: \"Après qu'il a fini, il est rentré\". Если главный глагол в будущем, после \"dès que\" ставят futur antérieur: \"Dès que tu auras fini, appelle-moi\"."],"concordance-des-temps":["Согласование времён","Когда главный глагол в прошедшем времени, глагол придаточного сдвигается назад: настоящее становится imparfait, passé composé — plus-que-parfait, будущее — условным. Нельзя сочетать главный глагол в прошедшем с настоящим в придаточном: \"Il pensait que nous étions partis\". Примеры: \"Je savais que tu viendrais\", \"Elle disait qu'elle était fatiguée\"."],"discours-indirect-passe":["Косвенная речь в прошлом","В косвенной речи после глагола в прошедшем (\"elle a dit que\") времена сдвигаются: настоящее — в imparfait, passé composé — в plus-que-parfait, будущее — в условное. Меняются и слова времени: \"demain\" становится \"le lendemain\", \"hier\" — \"la veille\", \"aujourd'hui\" — \"ce jour-là\". Пример: \"Il a dit qu'il viendrait le lendemain\"."],"discours-indirect-questions":["Косвенные вопросы","В косвенном вопросе порядок слов обычный, вопросительного знака нет. \"Est-ce que\" и вопросы да/нет заменяются на \"si\": \"Il a demandé si je venais\". \"Qu'est-ce que\" превращается в \"ce que\", а \"qu'est-ce qui\" — в \"ce qui\". После глагола в прошедшем сдвигаются и времена. Примеры: \"Elle m'a demandé ce que je voulais\", \"Il voulait savoir ce qui se passait\"."],"discours-indirect-ordres":["Передача приказов и просьб","Чтобы передать приказ или просьбу, используют \"dire de\" или \"demander de\" и инфинитив: \"Elle m'a dit de rentrer\". Адресат выражается через \"à\" или местоимение: \"Il a demandé à ses voisins de baisser la musique\". В отрицательном приказе \"ne pas\" стоит вместе перед инфинитивом: \"Il nous a dit de ne pas toucher aux câbles\"."],"accord-participe-cod-avant":["Согласование с предшествующим дополнением","С \"avoir\" причастие согласуется с прямым дополнением, только если оно стоит перед глаголом. Ищите \"que\", местоимение вроде \"les\" или вопросительное слово: \"Les lettres que Marie a écrites\", \"Quelle robe as-tu choisie ?\". Если дополнение стоит после, согласования нет: \"Marie a écrit des lettres\"."],"accord-participe-pronominaux":["Согласование причастия возвратных глаголов","В passé composé возвратного глагола причастие согласуется с возвратным местоимением, если оно прямое дополнение: \"Les amies se sont retrouvées\". Оно остаётся неизменным, если местоимение косвенное или дальше идёт другое дополнение: \"Elle s'est lavé les mains\", \"Ils se sont envoyé des messages\". Спросите себя: \"se\" значит \"à qui ?\" или \"qui ?\"."],"participe-present-gerondif":["Причастие, герундий, прилагательное","Герундий \"en + -ant\" говорит, как или когда что-то происходит, и неизменяем: \"Il s'est blessé en coupant du bois\". Причастие настоящего времени заменяет придаточное и тоже неизменяемо: \"Les enfants jouant dans le jardin\". Глагольное прилагательное согласуется с существительным: \"une histoire fascinante\", \"des résultats surprenants\"."],"passif-et-alternatives":["Пассив и его замены","Пассив строится из \"être\" и причастия: \"Les résultats ont été annoncés par le jury\". Французский часто предпочитает замены: возвратный глагол для общих фактов (\"Le fromage se mange après le plat\"), \"on\" или \"se faire\" для того, что случается с подлежащим (\"Il s'est fait voler son sac\")."],"causatif-faire-laisser":["Каузатив faire и laisser","\"Faire\" и инфинитив значит заставить сделать или сделать через другого: \"Nous avons fait refaire la cuisine\". \"Laisser\" и инфинитив значит разрешить: \"Le professeur a laissé les élèves partir\". Причастие \"fait\" перед инфинитивом неизменяемо: \"Ce film m'a fait pleurer\"."],"pronoms-relatifs-composes":["Сложные относительные местоимения","После предлога используют \"lequel\", \"laquelle\", \"lesquels\" или \"lesquelles\" по существительному: \"la table sur laquelle\", \"les amis chez lesquels\". С \"à\" они сливаются: \"auquel\", \"auxquels\", \"auxquelles\", \"à laquelle\". С \"de\" получаются \"duquel\", \"desquels\", \"de laquelle\"."],"pronom-relatif-dont":["Относительное местоимение dont","\"Dont\" заменяет \"de\" и существительное в определительном придаточном: \"L'ordinateur dont j'ai besoin\" (avoir besoin de). Оно выражает и принадлежность, существительное идёт сразу за ним: \"l'écrivain dont le dernier roman\". А ещё вводит часть группы: \"trois enfants, dont deux vivent à l'étranger\"."],"ce-qui-ce-que-ce-dont":["Ce qui, ce que, ce dont","\"Ce\" и относительное местоимение указывают на идею или безымянную вещь. \"Ce qui\" — подлежащее (\"Ce qui m'inquiète\"), \"ce que\" — дополнение (\"ce que tu veux\"). \"ce dont\" используют с глаголами, требующими \"de\" (\"ce dont tu as envie\"), а \"ce à quoi\" — с глаголами, требующими \"à\" (\"ce à quoi il s'intéresse\")."],"pronoms-doubles-ordre":["Порядок двух местоимений","Перед глаголом для me, te, nous и vous сначала ставят косвенное местоимение: \"Je te le rends\". Для третьего лица сначала прямое: \"Je le lui donne\"; \"en\" всегда последнее: \"Je lui en ai parlé\". После утвердительного повелительного порядок — прямое, затем косвенное: \"Donne-les-moi\"."],"pronoms-y-en-avances":["y и en: продвинутый уровень","\"En\" заменяет \"de\" и существительное или количество, а число остаётся: \"J'en ai acheté trois\". \"Y\" заменяет \"à\" или место: \"J'y pense tout le temps\". В утвердительном повелительном они идут после глагола и могут сочетаться: \"Donnez-m'en un kilo\"."],"mise-en-relief":["Выделение: c'est...qui/que","\"C'est ... qui\" выделяет подлежащее, а \"c'est ... que\" — дополнение или обстоятельство: \"C'est moi qui ai fait le gâteau\", \"C'est demain que nous partons\". С существительным во множественном числе — \"ce sont\": \"Ce sont mes voisins que j'ai invités\". Глагол после \"qui\" согласуется с выделенным элементом."],"inversion-peut-etre":["Инверсия после вводных наречий","В формальной речи после \"peut-être\", \"sans doute\" и \"aussi\" (в значении \"поэтому\") в начале фразы нужна инверсия подлежащего и глагола: \"Peut-être viendra-t-il demain\". Если подлежащее — существительное, повторите его местоимением. Если глагол кончается на гласную перед \"il\" или \"elle\", добавляют \"-t-\": \"viendra-t-elle\"."],"ne-expletif":["Пустое ne","После глаголов страха (\"craindre que\"), \"avant que\" и сравнительных степеней неравенства формальный французский добавляет \"ne\" без отрицательного смысла: \"Je crains qu'il ne pleuve\", \"avant qu'il ne fasse nuit\", \"plus grand que je ne pensais\". В речи оно необязательно и никогда не сочетается с \"pas\"."],"connecteurs-concession-opposition":["Уступка и противопоставление","\"Bien que\" и сослагательное, а также \"malgré\" и существительное выражают уступку: \"Malgré la pluie, nous sommes sortis\". \"Alors que\" и изъявительное противопоставляет два факта: \"Paul adore la mer, alors que sa femme préfère la montagne\". \"Pourtant\", \"cependant\" и \"en revanche\" связывают два предложения."],"nominalisation":["Превращаем глаголы в существительные","Номинализация делает текст лаконичнее и формальнее. Глаголы становятся существительными с окончаниями вроде -tion, -ment, -ure или -ée: \"ouvrir\" даёт \"l'ouverture\", \"augmenter\" — \"l'augmentation\", \"arriver\" — \"l'arrivée\". Так можно и с прилагательными: \"difficile\" даёт \"la difficulté\". Проверяйте род нового существительного."],"tout-accord":["Tout: прилагательное, местоимение, наречие","Как прилагательное \"tout\" согласуется с существительным: \"tous les magasins\", \"toutes les fenêtres\". Как наречие со значением \"совсем\" оно неизменяемо, кроме случая перед прилагательным женского рода на согласную: \"elle est tout étonnée\", но \"elles sont toutes timides\"."],"prepositions-apres-verbes":["Предлоги после глаголов","Некоторые глаголы требуют постоянного предлога, и он может менять смысл. \"Penser à\" значит думать о чём-то: \"Je pense à mes vacances\"; \"penser de\" спрашивает мнение: \"Que penses-tu de ce film ?\". Учите пары вроде \"s'habituer à\" и \"se méfier de\" как единое целое."],"infinitif-passe":["Прошедший инфинитив","\"Après\" с \"avoir\" или \"être\" и причастием показывает, что действие произошло раньше главного: \"Après avoir écrit la lettre, il l'a postée\". Подлежащее обоих действий должно быть одним. Глаголы движения и возвратные глаголы берут \"être\" и согласуются: \"Après être rentrée\", \"Après nous être reposés\"."],"a-regard-pronoms-lequel":["Вопросительное lequel","\"Lequel\" спрашивает о выборе среди известных вещей и согласуется с ними: \"Lequel de ces chemins ?\", \"Laquelle de tes amies ?\". С \"à\" или \"de\" оно сливается: \"Auquel de ces clients as-tu téléphoné ?\", \"Duquel parles-tu ?\". \"quel\" используют только непосредственно перед существительным."]};
